import java.util.ArrayDeque;

public class Solution {
    // Pilha de índices com temperaturas decrescentes; um dia mais quente resolve os topos menores.
    static int[] diasAteEsquentar(int[] temps) {
        int[] resp = new int[temps.length];
        ArrayDeque<Integer> pilha = new ArrayDeque<>();
        for (int i = 0; i < temps.length; i++) {
            while (!pilha.isEmpty() && temps[pilha.peek()] < temps[i]) {
                int j = pilha.pop();
                resp[j] = i - j;
            }
            pilha.push(i);
        }
        return resp;
    }
}

