import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplo() {
        assertArrayEquals(new int[]{1, 1, 4, 2, 1, 1, 0, 0}, Solution.diasAteEsquentar(new int[]{73, 74, 75, 71, 69, 72, 76, 73}));
    }

    @Test void iguaisNaoContam() {
        assertArrayEquals(new int[]{0, 0, 0}, Solution.diasAteEsquentar(new int[]{50, 50, 50}));
    }

    @Test void decrescenteGrande() {
        int n = 100_000;
        int[] t = new int[n];
        for (int i = 0; i < n; i++) t[i] = n - i;
        t[n - 1] = n + 1;
        int[] r = Solution.diasAteEsquentar(t);
        assertEquals(n - 1, r[0]);
        assertEquals(1, r[n - 2]);
    }
}

