import java.util.ArrayDeque;

public class Solution {
    // Pilha crescente; ao desempilhar a barra h, a largura vai do novo topo + 1 até i - 1. O(n).
    static long maiorRetangulo(int[] alturas) {
        ArrayDeque<Integer> pilha = new ArrayDeque<>();
        long melhor = 0;
        for (int i = 0; i <= alturas.length; i++) {
            int h = i == alturas.length ? 0 : alturas[i]; // sentinela de altura 0 esvazia a pilha
            while (!pilha.isEmpty() && alturas[pilha.peek()] >= h) {
                int altura = alturas[pilha.pop()];
                int esquerda = pilha.isEmpty() ? -1 : pilha.peek();
                melhor = Math.max(melhor, (long) altura * (i - esquerda - 1));
            }
            pilha.push(i);
        }
        return melhor;
    }
}

