import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplo() {
        assertEquals(10, Solution.maiorRetangulo(new int[]{2, 1, 5, 6, 2, 3}));
    }

    @Test void bordas() {
        assertEquals(0, Solution.maiorRetangulo(new int[]{}));
        assertEquals(7, Solution.maiorRetangulo(new int[]{7}));
        assertEquals(12, Solution.maiorRetangulo(new int[]{3, 3, 3, 3}));
    }

    @Test void areaGrande() {
        int[] a = new int[100_000];
        java.util.Arrays.fill(a, 100_000);
        assertEquals(10_000_000_000L, Solution.maiorRetangulo(a));
    }
}
